package com.cfrg.duelar

import android.content.SharedPreferences
import androidx.compose.foundation.Canvas
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp

@Composable
fun EmotionTimelineCard(prefs: SharedPreferences) {
    // ... other code ...

    val withData = loadEmotionData(prefs)

    val recentSignals = withData.sortedBy { it.day }.takeLast(3)
    val recentEmotionText = if (recentSignals.isNotEmpty()) {
        recentSignals
            .map { shortEmotionLabel(it.label) }
            .distinct()
            .joinToString(" · ")
    } else {
        "Sin registros"
    }
    val recentAverageIntensity = if (recentSignals.isNotEmpty()) {
        recentSignals.map { it.intensity }.average().toInt().coerceIn(1, 10)
    } else {
        0
    }

    Column(modifier = Modifier.padding(16.dp)) {
        Row(modifier = Modifier.fillMaxWidth()) {
            MiniMetric(
                title = "Últimas emociones",
                value = recentEmotionText,
                modifier = Modifier.weight(1f)
            )
            MiniMetric(
                title = "Intensidad promedio",
                value = if (recentAverageIntensity > 0) "$recentAverageIntensity/10" else "—",
                modifier = Modifier.weight(1f)
            )
        }
        // ... other UI components ...
    }
}

@Composable
fun EmotionLineChart(days: List<EmotionDay>) {
    Canvas(modifier = Modifier.fillMaxWidth().padding(16.dp)) {
        val dataDays = days

        val labelDays = dataDays
            .sortedBy { it.day }
            .takeLast(3)
            .map { it.day }
            .toSet()

        // ... other drawing code ...

        dataDays.forEach { item ->
            // ... drawing code ...

            if (item.day in labelDays) {
                val labelOffset = when (item.day) {
                    labelDays.minOrNull() -> 52f
                    labelDays.maxOrNull() -> 24f
                    else -> 38f
                }
                val labelY = (y - labelOffset).coerceAtLeast(28f)
                // Draw label at labelY
            }

            // ... other drawing code ...
        }
    }
}

